css:
@font-face {
	font-family: 'Que Grotesque';
	font-weight: 400;
	src: url('./fonts/QueGrotesque-Regular.woff2') format('woff2');
}

@font-face {
	font-family: 'Que Grotesque';
	font-weight: 600;
	src: url('./fonts/QueGrotesque-SemiBold.woff2') format('woff2');
}

* {
	box-sizing: border-box;
}

body {
	margin: 0;
	font-family: 'Que Grotesque', system-ui, sans-serif;
	font-size: 16px;
	line-height: 1.45;
	color: #1f1d1a;
	background: #fbf8f1;
}

.home.mk-s3kp4u {
				min-height: 100vh;
				width: 100%;
				max-width: 880px;
				margin: 0 auto;
				padding: 20px;
			}
			.bar.mk-s3kp4u {
				display: flex;
				align-items: center;
				justify-content: space-between;
				gap: 12px;
			}
			.pill.mk-s3kp4u {
				display: inline-flex;
				align-items: center;
				justify-content: center;
				min-height: 44px;
				padding: 10px 18px;
				border: 1px solid #c2410c;
				border-radius: 999px;
				background: #c2410c;
				color: #ffffff;
				text-decoration: none;
				font-weight: 600;
			}
			.row.mk-s3kp4u {
				display: block;
				color: inherit;
				text-decoration: none;
			}
			h1.mk-s3kp4u {
				margin: 0 0 16px;
				font-size: 28px;
				font-weight: 600;
				letter-spacing: -0.01em;
			}
